CID = 'intro'
RUNS, FIRST, COMM, SYN, ERR = "How Python runs your code", "Your first program: print()", "Comments: notes for humans", "The syntax rules that matter", "Errors are normal"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 T(1, FIRST, 'print("Price")\nprint(250 + 50)\nprint("250 + 50")', "Text inside quotes prints exactly as written. Without quotes, Python does the maths first and prints the answer."),
 W(1, FIRST, 'Print `Welcome to Python` on one line and `Day 1 of my data journey` on the next line.', '# Write two print() lines\n', 'print("Welcome to Python")\nprint("Day 1 of my data journey")', "Each `print()` starts a new line. Text goes inside quotes."),
 W(1, FIRST, 'A shop sold 48 pens in the morning and 37 pens in the evening. Print the total. Let Python do the maths.', '# Total pens sold today\n', '# Total pens sold today\nprint(48 + 37)', "Put the maths inside `print()` with no quotes, and Python works out `85` for you."),
 W(1, FIRST, 'A cinema hall has 18 rows with 24 seats in each row. Print the total number of seats.', '# Seats in the hall\n', '# Seats in the hall\nprint(18 * 24)', "In Python, multiply uses `*`. Python works out `18 * 24` and prints `432`."),
 F(1, SYN, "This code should print `Good morning`, but it crashes. Fix it.", 'Print("Good morning")', 'print("Good morning")', "Python is case-sensitive. The function is `print` in small letters. `Print` is a different name that does not exist, so you get a `NameError`."),
 F(1, SYN, "This code should print `Hyderabad`, but it crashes. Fix it.", 'print("Hyderabad\')', 'print("Hyderabad")', "Quotes must match. The text starts with `\"`, so it must also end with `\"`. Mixed quotes give a `SyntaxError`."),
 W(1, COMM, 'This code prints three lines. Turn the middle line into a comment, so only the first and the last lines print.', 'print("Step 1: open the file")\nprint("Step 2: this is a draft line")\nprint("Step 3: save the report")\n', 'print("Step 1: open the file")\n# print("Step 2: this is a draft line")\nprint("Step 3: save the report")', "Put `#` at the start of a line and Python skips it. This is a handy way to switch a line off without deleting it."),
 T(1, SYN, 'print(\'Guntur\', "Vizag")', "Single quotes and double quotes both make text, and the quotes themselves are not printed. The comma puts one space between the two values."),
 # ---------- Medium ----------
 T(2, COMM, '# print("A")\nprint("B")  # print("C")\nprint("D")', "Python ignores everything after `#` on a line, even if it looks like code. Only `B` and `D` are printed."),
 W(2, RUNS, 'A shop sold 45 boxes with 12 bottles in each box. Use ONE `print()` with a comma to print `Units sold: 540`. Let Python work out the 540.', '# One print() with a comma\n', 'print("Units sold:", 45 * 12)', "A comma inside `print()` separates two values and puts one space between them: the text, then the answer of the maths."),
 T(2, RUNS, 'city = "Pune"\ntemp = 29\nprint(city, temp)\ntemp = temp + 3\nprint(city, temp)', "Python runs from top to bottom. Line 4 works out `29 + 3` first, then stores 32 back in `temp`. The old value is gone."),
 W(2, FIRST, 'Print this line exactly: `Total: 3 x 40 = 120`. Python must work out the `120`. The rest is text.', '# The left part is text, the answer is maths\n', 'print("Total: 3 x 40 =", 3 * 40)', "Everything up to `=` is text, so it goes in quotes. The answer is maths, so it goes after a comma without quotes."),
 W(2, FIRST, 'A train left with 640 passengers. At the first stop 85 got off and 120 got on. Print the number of passengers now, in one line of maths.', '# Passengers on the train now\n', '# Passengers on the train now\nprint(640 - 85 + 120)', "`640 - 85 + 120` is worked out from left to right: 555, then 675."),
 W(2, COMM, 'The second line prints the wrong bill: 4 coffees at 25 rupees each. Switch that line off with a comment, then add a new line under it that prints the right bill.', 'print("Bill for 4 coffees")\nprint(4 + 25)\n', 'print("Bill for 4 coffees")\n# print(4 + 25)\nprint(4 * 25)', "`#` switches off the wrong line but keeps it for reference. The new line uses `*` to multiply: 4 times 25 is 100."),
 W(2, RUNS, 'The steps print in the wrong order. Move the lines so the output goes `1. Boil water`, `2. Add tea leaves`, `3. Serve hot`.', 'print("3. Serve hot")\nprint("1. Boil water")\nprint("2. Add tea leaves")\n', 'print("1. Boil water")\nprint("2. Add tea leaves")\nprint("3. Serve hot")', "Python always runs lines from top to bottom, so the order of the lines is the order of the output."),
 F(2, SYN, "This code should print `Pass`, but it stops with an `IndentationError`. Fix it.", 'if 75 > 40:\nprint("Pass")', 'if 75 > 40:\n    print("Pass")', "A line that ends with a colon `:` starts a block. The line inside the block must be pushed right by 4 spaces."),
 F(2, ERR, "This code should print `Total: 500`, but it stops with a `TypeError`. Fix it.", 'print("Total: " + 500)', 'print("Total:", 500)', "`+` cannot join text and a number: that is the `TypeError`. A comma inside `print()` shows both values, with a space between them."),
 W(2, FIRST, 'A tea stall sold 12 cups on Monday, 15 on Tuesday and 9 on Wednesday, at 40 rupees a cup. Use ONE `print()` to show the sales of each day: `480 600 360`.', '# Sales of three days on one line\n', 'print(12 * 40, 15 * 40, 9 * 40)', "One `print()` can show many values. Python works out each maths part, and the commas put a space between the answers."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, FIRST, 'Print this bill exactly, one line each. Python must work out every number after `=`:\n`Tea x 2 = 30` (15 rupees each)\n`Samosa x 3 = 36` (12 rupees each)\n`Total = 66` (add the two answers).', '# Bill: tea is 15, samosa is 12\n', 'print("Tea x 2 =", 2 * 15)\nprint("Samosa x 3 =", 3 * 12)\nprint("Total =", 30 + 36)', "Each line is text, a comma, then the maths. The text holds the `x` and `=` signs, and Python works out the numbers."),
 W(3, RUNS, 'Start with `cash = 2000` and print `Cash: 2000`. A customer pays 350: add it to `cash` and print `Cash: 2350`. Then you pay 500 rent: take it from `cash` and print `Cash: 1850`.', 'cash = 2000\n', 'cash = 2000\nprint("Cash:", cash)\ncash = cash + 350\nprint("Cash:", cash)\ncash = cash - 500\nprint("Cash:", cash)', "`cash = cash + 350` works out the right side first, then stores the answer back in `cash`. Each `print()` shows the value at that moment."),
 F(3, SYN, "This code has three mistakes: a note that is not a comment, a missing colon, and a capital letter. It should print `Report`, then `Done`. Fix it.", 'monthly report starts here\nif 10 > 3\n    print("Report")\nPrint("Done")', '# monthly report starts here\nif 10 > 3:\n    print("Report")\nprint("Done")', "A note needs `#` in front. A line that starts a block needs `:` at the end. And `print` is always written in small letters."),
 T(3, COMM, 'print("Room #12")  # top floor\n# print("Room #14")', "A `#` inside quotes is just text, so `Room #12` prints in full. The `#` after the closing bracket starts a comment, and the last line is all comment."),
 W(3, RUNS, 'This program prints the steps in the wrong order and has a debug line that should not print. Put the steps in order and switch off the debug line with a comment. The output must be `Step 1: load data`, `Step 2: clean data`, `Step 3: make chart`.', 'print("Step 2: clean data")\nprint("DEBUG: checking")\nprint("Step 3: make chart")\nprint("Step 1: load data")\n', 'print("Step 1: load data")\nprint("Step 2: clean data")\n# print("DEBUG: checking")\nprint("Step 3: make chart")', "Python runs lines from top to bottom, so move the lines into the right order. A `#` in front of the debug line keeps it in the file but stops it from running."),
 W(3, ERR, 'Each of these lines has a mistake:\n1. `print("Hi)`\n2. `prnt("Hi")`\n3. `print("Age: " + 25)`\nPrint the name of the error each one gives, one per line, in this order. (Try running each line to read its last error line.)', '# Print the three error names\n', 'print("SyntaxError")\nprint("NameError")\nprint("TypeError")', "A missing quote is a grammar mistake: `SyntaxError`. A misspelt name is unknown to Python: `NameError`. Text + number is a `TypeError`."),
 W(3, SYN, 'Python is case-sensitive, so `total`, `Total` and `TOTAL` are three different names. Store 100 in `total`, 200 in `Total` and 300 in `TOTAL`. Then print all three with one `print()` in this order: `TOTAL`, `total`, `Total`.', '# Three different names\n', 'total = 100\nTotal = 200\nTOTAL = 300\nprint(TOTAL, total, Total)', "Because capitals matter, the three names hold three separate values. The output is `300 100 200`."),
]
